// shared/i18n/admin.js
//
// Strings for the Admin section (pages/admin/*.html + their
// assets/js/admin/*.js). Internal ops tooling used by CM_Pro admins
// (app administrators) to manage users, app versions, bandwidth
// limits, push notifications, activity logs, and the shared
// wallpaper/background image — not the regular credit-officer-facing
// pages. Load alongside shared/i18n/common.js and shared/i18n/core.js
// on every pages/admin/*.html page.
//
// Key namespace: admin.<area>.<name> — admin.nav.* / admin.common.*
// are shared across all 7 admin pages (sidebar, topbar actions,
// shared modal primitives); the rest are grouped per page
// (admin.hub.*, admin.users.*, admin.appversions.*, admin.bandwidth.*,
// admin.notifications.*, admin.activitylogs.*, admin.wallpaper.*).

