  "admin.users.branchHintUser": { km: "ជ្រើសសាខា ដើម្បីឲ្យ User នេះទទួល Smart Alerts និងការរំលឹក CO របស់សាខានោះ («All Branch» = គ្រប់សាខា)។ សិទ្ធិមើលទិន្នន័យនៅដដែល (គ្រប់សាខា)។", en: "Pick a branch so this User receives that branch's Smart Alerts and officer reminders (All Branch = every branch). Their data access is unchanged (all branches)." },
  "admin.users.branchHintManager": { km: "អ្នកគ្រប់គ្រងមើលឃើញតែទិន្នន័យ និងទទួល Alert របស់សាខានេះ («All Branch» = គ្រប់សាខា)។", en: "The manager sees only this branch's data and receives its alerts (All Branch = every branch)." },
  "admin.users.roleDesc.admin": { km: "មើលទិន្នន័យគ្រប់សាខា។ Upload ទិន្នន័យទាំងអស់ (OS, Arrears T24, Overdue, WO, Debit Turnover …), កែ Master Data (Credit Officer / Location), ចូលទំព័រ Admin (អ្នកប្រើ, Smart Alerts, Snapshot, ការជូនដំណឹង, App Versions, Maintenance)។ ទទួល Smart Alerts និងការរំលឹក CO គ្រប់សាខា។", en: "Sees every branch. Uploads all data (OS, Arrears T24, Overdue, WO, Debit Turnover …), edits Master Data (Credit Officer / Location) and uses the Admin panel (users, Smart Alerts, snapshots, notifications, app versions, maintenance). Receives every branch's Smart Alerts and officer reminders." },
  "admin.users.roleDesc.user": { km: "មើលទិន្នន័យគ្រប់សាខា (Daily Arrears, Credit Report, CM Pro AI …)។ Upload ទិន្នន័យពី Excel/VBA (OS, Arrears T24, Overdue, WO, បញ្ជី Credit Officer, Address …) និងបំពេញ Reason Arrear។ មិនអាចចូល Admin, Upload Debit Turnover ឬកែ Master Data បានទេ។ ទទួល Smart Alerts និងការរំលឹក CO លុះត្រាតែកំណត់សាខា។", en: "Sees every branch (Daily Arrears, Credit Report, CM Pro AI …). Uploads Excel/VBA data (OS, Arrears T24, Overdue, WO, Credit Officer list, Address …) and fills Reason Arrear. No Admin panel, Debit Turnover upload or Master Data edits. Receives Smart Alerts and officer reminders only when a branch is set." },
  "admin.users.roleDesc.viewer_manager_a": { km: "ប្រធានសាខា៖ Daily Arrears, Credit Report និង CM Pro AI បង្ហាញតែសាខារបស់ខ្លួន («All Branch» = គ្រប់សាខា)។ បំពេញ Reason Arrear, កែ Arrear ក្រៅតំបន់, Spot Check។ មិនអាច Upload ទិន្នន័យទេ។ ទទួល Smart Alerts និងការរំលឹក CO នៃសាខា ហើយអាចតម្រងតាមសាខា / CO-FSRO ក្នុងទំព័រព័ត៌មានលម្អិត។", en: "Branch manager: Daily Arrears, Credit Report and CM Pro AI show only their branch (All Branch = all). Fills Reason Arrear, edits Out of Area arrears, Spot Check. Cannot upload data. Receives the branch's Smart Alerts and officer reminders, and can filter them by branch / CO-FSRO on the detail page." },
